using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Data;
using System.Windows.Media;
namespace AnoWowItemEditor;

internal sealed class ContentHistoryWindow : Window
{
    private readonly DataGrid list=new();
    private readonly StackPanel beforePreview=new(),afterPreview=new();
    private readonly TextBox search=new(),detail=new(){IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};
    private readonly ComboBox state=new(){DisplayMemberPath="Label"};
    private readonly CheckBox removed=new(){Content="Show removed entries",Foreground=Brushes.LightGray};
    private readonly Button toggle=new(){Content="Revert / reapply",IsEnabled=false},hide=new(){Content="Remove from history",IsEnabled=false};
    private readonly TextBlock feedback=new(){TextWrapping=TextWrapping.Wrap};
    private List<ContentOperation> operations=[];
    private readonly ReferenceCatalog references;
    private readonly CatalogResult? catalog;
    private readonly ItemKindFilter? itemKinds;
    private bool busy;
    internal bool Changed {get;private set;}
    internal ContentHistoryWindow(ReferenceCatalog references,CatalogResult? catalog=null)
    {
        this.references=references;this.catalog=catalog;if(catalog is not null)itemKinds=new(catalog.Tooltips,true);Title="Item, set-bonus & weapon-proc edits";Width=1200;Height=800;MinWidth=900;MinHeight=600;WindowStartupLocation=WindowStartupLocation.CenterOwner;Background=new SolidColorBrush(Color.FromRgb(35,36,40));
        var layout=new DockPanel{Margin=new Thickness(20)};Content=layout;
        var top=new StackPanel();DockPanel.SetDock(top,Dock.Top);layout.Children.Add(top);top.Children.Add(new TextBlock{Text=Title,FontSize=24,Margin=new Thickness(0,0,0,12),Foreground=Brushes.LightSkyBlue});
        var filters=new WrapPanel{Margin=new Thickness(0,0,0,12)};top.Children.Add(filters);search.Width=350;search.Margin=new Thickness(0,0,12,0);search.ToolTip="Search name, entity ID or operation ID";filters.Children.Add(search);state.Width=150;state.Margin=new Thickness(0,0,12,0);state.ItemsSource=new[]{new FilterChoice(-1,"All states"),new(1,"Active"),new(0,"Inactive")};state.SelectedIndex=0;filters.Children.Add(state);filters.Children.Add(removed);if(itemKinds is not null){filters.Children.Add(itemKinds);itemKinds.Changed+=Filter;}
        var actions=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(0,0,0,12)};top.Children.Add(actions);toggle.Margin=hide.Margin=new Thickness(0,0,12,0);actions.Children.Add(toggle);actions.Children.Add(hide);var refresh=new Button{Content="Refresh"};refresh.Click+=async(_,_)=>await Load();actions.Children.Add(refresh);
        feedback.Margin=new Thickness(0,12,0,0);DockPanel.SetDock(feedback,Dock.Bottom);layout.Children.Add(feedback);
        var body=new Grid();body.ColumnDefinitions.Add(new());body.ColumnDefinitions.Add(new(){Width=new GridLength(14)});body.ColumnDefinitions.Add(new());layout.Children.Add(body);
        list.Columns.Add(SpellPicker.Column("Name","Name",2));list.Columns.Add(SpellPicker.Column("Type","Kind"));list.Columns.Add(SpellPicker.Column("ID","EntityId"));list.Columns.Add(SpellPicker.Column("Active","Active"));list.Columns.Add(SpellPicker.Column("Saved","RecordedUtc",1.5));body.Children.Add(list);var right=new TabControl();right.Items.Add(new TabItem{Header="History details",Content=detail});var previews=new Grid();previews.ColumnDefinitions.Add(new());previews.ColumnDefinitions.Add(new());previews.Children.Add(DesignerWindow.Preview(beforePreview,"ORIGINAL"));var after=DesignerWindow.Preview(afterPreview,"RETAINED MODIFIED");Grid.SetColumn(after,1);previews.Children.Add(after);right.Items.Add(new TabItem{Header="Item previews",Content=previews});Grid.SetColumn(right,2);body.Children.Add(right);
        search.TextChanged+=(_,_)=>Filter();state.SelectionChanged+=(_,_)=>Filter();removed.Checked+=(_,_)=>Filter();removed.Unchecked+=(_,_)=>Filter();list.SelectionChanged+=(_,_)=>Selection();
        toggle.Click+=async(_,_)=>await Toggle();hide.Click+=async(_,_)=>await Hide();Loaded+=async(_,_)=>await Load();Closing+=(_,e)=>e.Cancel=busy;
    }
    private async Task Load(){try{operations=await ContentEditing.ListAsync();Filter();}catch(Exception ex){feedback.Text=ex.Message;}}
    private void Filter(){string? selected=(list.SelectedItem as ContentOperation)?.Id;int active=(state.SelectedItem as FilterChoice)?.Id??-1;string query=search.Text.Trim();list.ItemsSource=operations.Where(o=>MatchesItemKind(o)&&(!o.Hidden||removed.IsChecked==true||o.Active)&&(active<0||o.Active==(active==1))&&(query.Length==0||o.Name.Contains(query,StringComparison.OrdinalIgnoreCase)||o.EntityId.ToString()==query||o.Id.Equals(query,StringComparison.OrdinalIgnoreCase))).ToList();list.SelectedItem=((List<ContentOperation>)list.ItemsSource).FirstOrDefault(o=>o.Id==selected);if(list.SelectedItem is null)list.SelectedIndex=0;Selection();}
    private bool MatchesItemKind(ContentOperation op)
    {
        if(itemKinds is null||catalog is null)return true;
        var snapshot=JsonSerializer.Deserialize<ItemSnapshot>(op.After)!;var candidates=new List<CatalogItem>();
        CatalogItem? Item(ItemSnapshot part,int id){var fields=HotfixReader.Merge(catalog.Originals.GetValueOrDefault(id)?.Fields,HotfixHistory.SnapshotItem(HistoryActions.Serialize(part),id)?.Fields??new());if(part.OriginalItem?.GetValueOrDefault("ID")==id.ToString())fields=HotfixReader.Merge(fields,part.OriginalItem);return fields.ContainsKey("Display")?new(fields):catalog.Items.FirstOrDefault(i=>i.Id==id);}
        if(op.Kind is "Item" or "Clone" or "ItemDrops" or "Proc"){var item=Item(snapshot,op.EntityId);if(item is not null)candidates.Add(item);}
        else if(op.Kind is "NewSet" or "SetMembers"){foreach(var key in snapshot.Tables.Keys.Where(k=>k.StartsWith("piece_")&&k.EndsWith("_item_sparse"))){string prefix=key[..^"item_sparse".Length];var part=new ItemSnapshot(snapshot.Tables.Where(p=>p.Key.StartsWith(prefix)).ToDictionary(p=>p.Key[prefix.Length..],p=>p.Value));foreach(var row in part.Tables["item_sparse"]){var item=Item(part,int.Parse(row["ID"]!));if(item is not null)candidates.Add(item);}}}
        else if(op.Kind=="Set"&&catalog.Tooltips.Sets.TryGetValue(op.EntityId,out var set))candidates.AddRange(catalog.Items.Where(i=>set.Members.Contains(i.Id)));
        return candidates.Count==0?(itemKinds.ItemClass.SelectedIndex==0&&itemKinds.Subtype.SelectedIndex==0):candidates.Any(itemKinds.Matches);
    }
    private void Selection(){if(list.SelectedItem is not ContentOperation op){detail.Text="No matching edits.";TooltipView.Fill(beforePreview,Array.Empty<TooltipLine>());TooltipView.Fill(afterPreview,Array.Empty<TooltipLine>());toggle.IsEnabled=hide.IsEnabled=false;return;}toggle.Content=op.Active?"Revert…":"Reapply…";hide.Content=op.Hidden?"Restore to history":"Remove from history";toggle.IsEnabled=!busy;hide.IsEnabled=!busy&&!op.Active;detail.Text=$"{op.Name} · {op.Kind} {op.EntityId}\n{(op.Active?"ACTIVE":"INACTIVE")}{(op.Hidden?" · REMOVED":"")} · Version {op.Version}\nSaved UTC: {op.RecordedUtc}\nOperation: {op.Id}\n\nORIGINAL · BEFORE THIS EDIT\n{Summary(op.Before,op.Kind)}\n\nRETAINED MODIFIED VERSION\n{Summary(op.After,op.Kind)}\n\nSpell descriptions use the current reference catalog. Full raw snapshots remain in the audit database.";detail.ScrollToHome();RenderPreviews(op);}
    private void RenderPreviews(ContentOperation op)
    {
        if(catalog is null)return;var lookup=catalog.Items.ToDictionary(i=>i.Id);
        void Render(StackPanel panel,string json){try{var snapshot=JsonSerializer.Deserialize<ItemSnapshot>(json)!;var fields=HotfixReader.Merge(catalog.Originals.GetValueOrDefault(op.EntityId)?.Fields,HotfixHistory.SnapshotItem(json,op.EntityId)?.Fields??new());if(fields.ContainsKey("Display")){var item=new CatalogItem(fields);TooltipView.Fill(panel,ItemTooltip.Build(item,catalog.Tooltips,lookup));return;}var members=new List<CatalogItem>();foreach(var table in snapshot.Tables.Where(p=>p.Key.StartsWith("piece_")&&p.Key.EndsWith("_item_sparse")))foreach(var row in table.Value){var values=row.ToDictionary(p=>p.Key,p=>p.Value??"",StringComparer.OrdinalIgnoreCase);int id=TooltipData.Number(values,"ID");members.Add(new(HotfixReader.Merge(lookup.GetValueOrDefault(id)?.Fields,values)));}if(members.Count==0&&catalog.Tooltips.Sets.TryGetValue(op.EntityId,out var set))members.AddRange(set.Members.Where(lookup.ContainsKey).Select(id=>lookup[id]));if(members.Count==0&&lookup.TryGetValue(op.EntityId,out var selected))members.Add(selected);if(members.Count>0){var worn=SetDesignReview.Equip(new(new(0,"History outfit",60,1,false,0),[]),members,lookup,60).Slots;TooltipView.Fill(panel,ItemTooltip.Build(members[0],catalog.Tooltips,lookup));ItemVisualPreview.Outfit(panel,worn);}else TooltipView.Fill(panel,[new("No item appearance in this history entry.",ItemTooltip.Gray)]);}catch(Exception ex){TooltipView.Fill(panel,[new(ex.Message,ItemTooltip.Gray)]);}}
        Render(beforePreview,op.Before);Render(afterPreview,op.After);
    }
    private string Summary(string json,string kind){var snapshot=JsonSerializer.Deserialize<ItemSnapshot>(json)!;if(kind=="SetMembers"){var setRow=snapshot.Tables["new_set"].FirstOrDefault();if(setRow is null)return "No set definition.";var memberIds=Enumerable.Range(1,17).Select(n=>setRow.GetValueOrDefault("ItemID"+n)).Where(id=>id is not null&&id!="0");return "Set: "+setRow.GetValueOrDefault("Name")+"\nMembers: "+string.Join(", ",memberIds)+"\n"+string.Join("\n",snapshot.Tables.Where(p=>p.Key.StartsWith("piece_")&&p.Key.EndsWith("_item_sparse")).SelectMany(p=>p.Value).Select(r=>$"{r.GetValueOrDefault("Display")} · Item {r.GetValueOrDefault("ID")} · Set {r.GetValueOrDefault("ItemSet")}"));}if(kind is "NewSet" or "SetMembers")return ItemEditing.SnapshotSummary(snapshot)+"\n\nBonuses: "+string.Join("; ",snapshot.ContentRows?.Select(r=>$"({r.Pieces}) {references.Data.SpellName(r.SpellId)}")??[])+"\nWorld drop rows: "+snapshot.Tables.GetValueOrDefault("world_loot")?.Count;
        if(kind=="ItemDrops")return ItemEditing.SnapshotSummary(snapshot)+"\n\nCREATURE DROP LOCATIONS\n"+(snapshot.Tables["world_drop_policy"].FirstOrDefault() is {} policy?JsonSerializer.Deserialize<DropPlan>(policy["PlanJson"]!)!.Summary:"Unmanaged original drops")+"\n"+string.Join("\n",snapshot.Tables["world_loot"].Select(r=>$"Loot table {r["Entry"]} · {r["Chance"]}% · {r.GetValueOrDefault("Comment")}"));if(kind is "Item" or "Clone")return ItemEditing.SnapshotSummary(snapshot);return snapshot.ContentRows is {Length:>0} rows?string.Join("\n\n",rows.Select(r=>$"{references.Data.SpellName(r.SpellId)} · Spell {r.SpellId}\n"+(kind=="Set"?$"{r.Pieces} pieces · Spec {r.Specialization} · Trait {r.Trait}":$"{ReferenceCatalog.Trigger(r.Trigger)} · Cooldown {r.Cooldown} ms · Category cooldown {r.CategoryCooldown} ms · Charges {r.Charges} · Slot {r.Slot} · Category {r.Category} · Spec {r.Specialization} · Condition {r.Condition}")+"\n"+references.Data.SpellDescription(r.SpellId))):"No assignments.";}
    private async Task Toggle(){if(busy||list.SelectedItem is not ContentOperation op)return;var review=new ContentReviewWindow(op.Kind,op.Name,Summary(op.Active?op.After:op.Before,op.Kind),Summary(op.Active?op.Before:op.After,op.Kind)){Owner=this};if(review.ShowDialog()!=true)return;busy=true;list.IsEnabled=false;Selection();try{await ContentEditing.ToggleAsync(op);Changed=true;await Load();feedback.Text="Saved. Reload the server and verify in game.";}catch(Exception ex){feedback.Text=ex.Message;}finally{busy=false;list.IsEnabled=true;Selection();}}
    private new async Task Hide(){if(busy||list.SelectedItem is not ContentOperation op||op.Active)return;busy=true;Selection();try{await ContentEditing.SetOperationHiddenAsync(op,!op.Hidden);await Load();feedback.Text=op.Hidden?"Restored to history.":"Removed from the list. Stored payloads and audit events are retained.";}catch(Exception ex){feedback.Text=ex.Message;}finally{busy=false;Selection();}}
}
